from scipy.optimize import curve_fit
def f1(e,a,b,c,d): return a+b*(1-np.exp(-c*e))+d*e
for lo in np.arange(2,6,0.5):
    m=(T>=lo)&(T<lo+0.5)
    try:
        p,_=curve_fit(f1,eps[m],sigma[m],p0=[0.3,8,0.8,1.5],maxfev=20000)
        print(round(lo,1), m.sum(), np.round(p,4), np.std(sigma[m]-f1(eps[m],*p)))
    except Exception as ex: print(lo,ex)
